// Get current language from query parameter or session
session_start();
$currentLang = $_GET['lang'] ?? $_SESSION['lang'] ?? 'en';
$_SESSION['lang'] = $currentLang;

// Get filter and search parameters
$filter = $_GET['filter'] ?? 'all';
$search = $_GET['search'] ?? '';
$page = isset($_GET['page']) ? (int)$_GET['page'] : 1;
$itemsPerPage = 12;

// Filter vocabulary data
$filteredData = $vocabularyData;

// Apply type filter
if ($filter !== 'all') {
    $filteredData = array_filter($filteredData, function($word) use ($filter) {
        return isset($word['category']) && strtolower($word['category']) === strtolower($filter);
    });
}

// Apply search filter
if (!empty($search)) {
    $filteredData = array_filter($filteredData, function($word) use ($search) {
        return stripos($word['kanji'] ?? '', $search) !== false ||
               stripos($word['hiragana'] ?? '', $search) !== false ||
               stripos($word['romaji'] ?? '', $search) !== false ||
               stripos($word['meaning'] ?? '', $search) !== false ||
               stripos($word['sinhala'] ?? '', $search) !== false;
    });
}


// Reset array keys
$filteredData = array_values($filteredData);

// Calculate pagination
$totalWords = count($vocabularyData);
$totalFiltered = count($filteredData);
$totalPages = ceil($totalFiltered / $itemsPerPage);
$page = max(1, min($page, $totalPages));
$offset = ($page - 1) * $itemsPerPage;
$pageData = array_slice($filteredData, $offset, $itemsPerPage);

// Helper function to generate URL with parameters
function buildUrl($params = []) {
    global $currentLang, $filter, $search, $page;
    $defaults = [
        'lang' => $currentLang,
        'filter' => $filter,
        'search' => $search,
        'page' => $page
    ];
    $merged = array_merge($defaults, $params);
    return '?' . http_build_query(array_filter($merged));
}
